contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount1, uint amount2, address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(amount1 > 0);
        require(amount2 > 0);
        require(other != address(this));
        require(address(this).balance >= amount1 + amount2);

        uint balBefore = address(c).balance;

        c.deposit{value: amount1}(); if (__ESBMC_reverted()) return;
        uint balAfter1 = address(c).balance;
        c.deposit{value: amount2}(); if (__ESBMC_reverted()) return;
        uint balAfter2 = address(c).balance;

        assert(balAfter1 == balBefore + amount1 && balAfter2 == balAfter1 + amount2);
    }

    receive() external payable {}
}

