// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount1, uint256 amount2, address other) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        vm.assume(other != address(this));
        vm.assume(address(this).balance >= amount1 + amount2);
        uint balBefore = address(c).balance;
        try c.deposit{value: amount1}() {} catch { return; }
        uint balAfter1 = address(c).balance;
        try c.deposit{value: amount2}() {} catch { return; }
        uint balAfter2 = address(c).balance;
        assertTrue(balAfter1 == balBefore + amount1 && balAfter2 == balAfter1 + amount2);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2, address other) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount1, amount2, other);
    }

    receive() external payable {}
}
